  // Krio translations for the role-specific staff manuals.
  Object.assign(DICT.kri, {
  "Technical Director User Manual": "Manyual fɔ Teknikal Direktɔ",
  "This guide covers platform-level administration, developer access, security controls and application-wide maintenance.": "Dis manyual de sho hao fɔ manij di ɔl platform, ɛntri fɔ Developer, kɔntrol fɔ sikyuriti ɛn maintɛnans fɔ ɔl di app.",
  "Platform overview": "Ɔvaview fɔ platform",
  "Open the Technical Director portal and review the live totals for accounts, fixtures, clubs, fan reports and media posts.": "Opɛn portal fɔ Teknikal Direktɔ ɛn luk di nɔmba dɛn fɔ akawnt, mach we dɛn set, klob, ripɔt fɔ fan dɛn ɛn media post dɛn.",
  "Use Refresh overview to request the latest database counts. A dash means a count could not be read; it is not a zero.": "Yuz Frɛsh Ɔvaview fɔ gɛt di lɛst nɔmba frɔm database. Sɛ yu si dash, e min se nɔ able fɔ rid di nɔmba; e nɔ min se nɔmba na zero.",
  "Accounts and role assignments": "Akawnt ɛn fɔ gi rul",
  "For a new assignment, enter the person’s full name and email address. The email is the unique account identifier.": "Fɔ gi pɔsin nyu jɔb, put ɔl di pɔsin nem ɛn imel adrɛs. Imel na im di speshal ID fɔ akawnt.",
  "Select a JPG, PNG or WebP profile photo no larger than 4 MB if a photo is required.": "Pik JPG, PNG ɔ WebP foto fɔ prɔfayl we nɔ big pas 4 MB sɛ foto nid fɔ de.",
  "Choose only an approved role and save the assignment. Check Pending role assignments and All accounts and roles afterwards.": "Pik rul we dɛn don apruv nɔmɔ ɛn sev di jɔb. Afta dat, chɛk rul we de wet ɛn ɔl akawnt ɛn rul dɛn.",
  "Review role changes, account status and audit information. Suspend or delete accounts only with proper authorization.": "Luk chenj fɔ rul, stetis fɔ akawnt ɛn rikɔd fɔ wok dɛn. Suspend ɔ delit akawnt nɔmɔ sɛ yu gɛt ɔfishal pɔmit.",
  "League pause and whole-app freeze": "Pawz fɔ lig ɛn fɔ blok ɔl di app",
  "Pause league operations only when league-specific operations must stop. Resume them when authorized.": "Pawz wok fɔ lig nɔmɔ wen ɛn nid fɔ stop wok fɔ di lig. Bigin bak afta yu gɛt pɔmit.",
  "Freeze the entire app only for a genuine platform maintenance or security reason. This blocks staff portal access for non-developer roles.": "Freeze ɔl di app nɔmɔ fɔ tru maintɛnans ɔ sikyuriti problem. Dis go blok staff dɛn we nɔ bi Developer fɔ ɛntə portal.",
  "Before freezing, communicate the reason to relevant administrators. Unfreeze as soon as the issue is resolved.": "Bifo yu freeze am, toktok gi admin dɛn we nid fɔ no di rizɔn. Unfreeze am kwik wen dɛn don fiks di problem.",
  "A league pause and an application freeze are different controls.": "Pawz fɔ lig ɛn freeze fɔ ɔl app na tu difrɛn kɔntrol.",
  "Security and good practice": "Sikyuriti ɛn gud prɛktis",
  "Never share your password or leave an administrative session open on a shared device.": "Neba gi ɛni pɔsin yu paswɔd, ɔ lef admin sɛshɔn opɛn na divays we ɔda pipul de yuz.",
  "Verify names, email addresses, competition details and intended role before saving.": "Chɛk nem dɛn, imel adrɛs, dɛtɛl fɔ kɔmpitishɔn ɛn rul we yu want bifo yu sev.",
  "Use audit records to review administrative changes. Do not use a test account to alter live competition information.": "Yuz audit rikɔd fɔ luk admin chenj dɛn. Nɔ yuz test akawnt fɔ chenj infomeshɔn fɔ kɔmpitishɔn we de wok.",
  "Super Admin User Manual": "Manyual fɔ Big Admin",
  "Use this portal to manage approved league operations and public information. Confirm the competition and season before making changes.": "Yuz dis portal fɔ manij wok fɔ lig we dɛn apruv ɛn infomeshɔn fɔ pɔblik. Kɔnfɔm kɔmpitishɔn ɛn sezon bifo yu mek chenj.",
  "Command Centre": "Sɛntə fɔ kɔmɔnd",
  "Review the operational totals for competitions, seasons, fixtures/results, clubs, squad records and fan reports.": "Luk nɔmba fɔ kɔmpitishɔn dɛn, sezon dɛn, mach/rizɔlt dɛn, klob dɛn, rikɔd fɔ pleya dɛn ɛn ripɔt fɔ fan dɛn.",
  "Use Refresh overview when you need updated counts. Unavailable counts can indicate permissions or connectivity issues.": "Yuz Frɛsh Ɔvaview wen yu nid nyu nɔmba dɛn. Nɔmba we nɔ de fit min se pɔmit ɔ kɔnɛkshɔn gɛt problem.",
  "Competition directory management": "Manij list fɔ kɔmpitishɔn",
  "Open Competition directory management to create or maintain competitions and leagues, including the authorised men’s and women’s competitions and any approved cup tournaments.": "Opɛn Manij List fɔ Kɔmpitishɔn fɔ mek ɔ manij kɔmpitishɔn ɛn lig dɛn, we man dɛn ɛn uman dɛn kɔmpitishɔn ɛn ɛni cup tɔnamɛnt we dɛn apruv.",
  "Choose an existing competition to edit, or leave the selector on Create a new competition.": "Pik kɔmpitishɔn we de finis fɔ edit am, ɔ lef selector na Mek nyu kɔmpitishɔn.",
  "Enter the official competition name, format, category and public description. Add a valid logo URL or repository path only when an approved asset is available.": "Put ɔfishal nem fɔ kɔmpitishɔn, fɔmat, kayɛgori ɛn diskripsɔn fɔ pɔblik. Ad logo URL ɔ fayl path we valid nɔmɔ wen dɛn don apruv di piktchɔ.",
  "Set the display order and choose whether the competition should be published in the public League Centre, then select Save competition.": "Set di ɔda fɔ sho dɛn ɛn pik sɛ kɔmpitishɔn fɔ sho na pɔblik League Centre. Den pik Sev kɔmpitishɔn.",
  "After saving, confirm the competition appears correctly in the directory. Check its name, category, publication status and ordering before proceeding to clubs, seasons and fixtures.": "Afta yu sev am, kɔnfɔm se kɔmpitishɔn sho fayn na list. Chɛk nem, kayɛgori, status fɔ publish ɛn ɔda bifo yu go na klob, sezon ɛn mach dɛn.",
  "Knockout cup bracket": "Braket fɔ knockout cup",
  "Open Knockout cup bracket to configure the authorised cup tournament ties and progression.": "Opɛn Braket fɔ Knockout Cup fɔ set mach tie dɛn ɛn wetin go apin afta am fɔ cup tɔnamɛnt we dɛn apruv.",
  "Choose the cup competition, season and the fixture that represents the tie. Enter the round name and tie number.": "Pik cup kɔmpitishɔn, sezon ɛn mach we na im dis tie. Put nem fɔ rawn ɛn nɔmba fɔ tie.",
  "If the winner progresses, choose the next-round tie and whether the winner enters as the home or away team. Create the next-round fixture first in Fixture planner.": "Sɛ di tim we win go na nex rawn, pik di nex tie ɛn pik sɛ e go ple as os tim ɔ ɔda tim. Fɔs mek nex rawn mach na Fixture Planner.",
  "Save the tie and verify it appears in the bracket. After the match is officially completed, select the official winner and use Confirm winner and advance. Check the linked next-round fixture afterwards.": "Sev di tie ɛn chɛk se e sho na braket. Afta mach don ɔfishali, pik tim we win ɛn yuz Kɔnfɔm tim we win ɛn mek e go fɔwod. Afta dat, chɛk nex rawn mach we dɛn link.",
  "The bracket supports single-match ties. Confirm any competition-specific tie rules before recording a winner.": "Dis braket de wok fɔ tie we gɛt wan mach. Kɔnfɔm rul fɔ di kɔmpitishɔn bifo yu rikɔd tim we win.",
  "Clubs and seasons": "Klob ɛn sezon dɛn",
  "To add a club, enter its official club name, choose its competition and optionally add a valid crest URL, then select Add club.": "Fɔ ad klob, put ɔfishal nem fɔ klob, pik im kɔmpitishɔn ɛn yu fit ad valid crest URL, den pik Ad klob.",
  "Create seasons with a clear season name and correct start and end dates. Check the season list after saving.": "Mek sezon wit klia nem ɛn di rait dɛt fɔ bigin ɛn fɔ ɛnd. Chɛk list fɔ sezon afta yu sev.",
  "Avoid creating duplicate club or season records. Confirm spelling and competition first.": "Nɔ mek tu sem rikɔd fɔ klob ɔ sezon. Fɔs kɔnfɔm spel ɛn kɔmpitishɔn.",
  "Historical league standings": "Tebul fɔ lig we don pas",
  "Choose the league competition and a past season. The current season cannot be selected because its table is calculated from match results.": "Pik lig kɔmpitishɔn ɛn sezon we don pas. Yu nɔ fit pik sezon we de go nɔw bikɔs dɛn de kɔmpyut im tebul frɔm rizɔlt fɔ mach.",
  "For bulk entry, download the historical standings CSV template, enter one row per club, choose the file and select Check CSV. Correct every reported issue before selecting Import standings.": "Fɔ put mɔni rikɔd at wan tɛm, dɔnlod CSV template fɔ ol tebul. Put wan row fɔ ɛni klob, pik fayl ɛn pik Chɛk CSV. Fiks ɔl problem dɛn bifo yu pik Impɔt tebul.",
  "For manual entry, select Load table. Existing saved rows are loaded for editing; if no table exists, the current active clubs are offered as a starting list. Type the final position, played, wins, draws, losses, goals for, goals against and points. Add or remove club rows as needed.": "Fɔ put am bay yu han, pik Lod tebul. Dɛn go lod row dɛn we dɛn don sev fɔ yu edit; sɛ nɔ gɛt tebul, dɛn go sho klob dɛn we de wok fɔ yu bigin. Put pozishɔn, mach ple, win, draw, lus, gɔl we dɛn skɔ, gɔl we dɛn gɛt agens ɛn pɔynt. Ad ɔ tek weh row fɔ klob sɛ yu nid.",
  "Played must equal wins plus draws plus losses. Each club and position must appear only once. Points are entered as the official final points, including any deductions.": "Mach ple fɔ bi sem wit win plas draw plas lus. Ɛni klob ɛn pozishɔn fɔ apia wan tɛm nɔmɔ. Put ɔfishal final pɔynt dɛn, we go include eni pɔynt dɛn we dɛn tek weh.",
  "Saving replaces only the historical table for the selected league and past season. It does not change match fixtures, match scores or the current live table. The published table can be viewed on the public League Pages by selecting its season.": "Wen yu sev am, e go chenj tebul fɔ di lig ɛn sezon we yu pik nɔmɔ. E nɔ go chenj mach dɛn, skɔ fɔ mach ɔ tebul fɔ sezon we de go nɔw. Pipul fit luk tebul we dɛn publish na pɔblik League Pages by pik sezon.",
  "Fixture planner": "Plɛn fɔ mach dɛn",
  "Choose the competition and season before entering the home team, away team, kick-off date/time and venue.": "Pik kɔmpitishɔn ɛn sezon bifo yu put os tim, ɔda tim, dɛt/tɛm fɔ mach bigin ɛn ples.",
  "Check both team names and the date carefully, then select Add fixture.": "Chɛk nem fɔ tu tim ɛn dɛt gud, den pik Ad mach.",
  "Confirm the fixture appears in the relevant match lists.": "Kɔnfɔm se mach de na list fɔ mach we e fɔ go.",
  "Import fixtures and results": "Impɔt mach ɛn rizɔlt dɛn",
  "Download the CSV template and follow its column structure exactly.": "Dɔnlod CSV template ɛn fɔlɔ di kolɔm strɔkchɔ sem sem.",
  "Ensure season, competition and club names match existing records.": "Mek shɔ se nem fɔ sezon, kɔmpitishɔn ɛn klob dɛn sem wit rikɔd we de.",
  "Choose the CSV file and select Check file. Review the preview and resolve validation errors before selecting Import matches.": "Pik CSV fayl ɛn pik Chɛk fayl. Luk preview ɛn fiks ɛrɔ dɛn bifo yu pik Impɔt mach dɛn.",
  "Do not import the same file twice.": "Nɔ impɔt sem fayl tu tɛm.",
  "Results and match status": "Rizɔlt ɛn stetis fɔ mach",
  "Choose the correct season and match, then enter the home and away scores.": "Pik di rait sezon ɛn mach, den put skɔ fɔ os tim ɛn ɔda tim.",
  "Use Record result for a new result. Changing or reversing a confirmed result requires a reason and is logged.": "Yuz Rikɔd rizɔlt fɔ nyu rizɔlt. Fɔ chenj ɔ kansul rizɔlt we dɛn don kɔnfɔm yu fɔ gi rizɔn, ɛn dɛn go rikɔd di wok.",
  "Use Match status to mark a fixture scheduled, postponed, rescheduled or cancelled. Enter a clear reason where appropriate.": "Yuz Stetis fɔ mach fɔ mark sɛ dɛn set mach, dɛn pas am go na ɔda dɛt, dɛn set am fɔ nyu dɛt ɔ dɛn kansul am. Put klia rizɔn sɛ e nid.",
  "Verify the public table and match centre after an approved result.": "Afta dɛn apruv rizɔlt, chɛk pɔblik tebul ɛn Match Centre.",
  "Referee assignments and approvals": "Jɔb fɔ refri ɛn apruv",
  "Choose a fixture and the official, then select the match role and assign.": "Pik mach we dɛn set ɛn ɔfishal pɔsin, den pik im rul na mach ɛn gi am di jɔb.",
  "Review final scores submitted by referees before approval. Check the match and score against the official report.": "Luk final skɔ we refri dɛn sɛnd bifo yu apruv. Chɛk mach ɛn skɔ wit ɔfishal ripɔt.",
  "Review submitted news and fan comments before approving or rejecting them.": "Luk nyuz ɛn wetin fan dɛn tɔk we dɛn sɛnd bifo yu apruv ɔ nɔ apruv dɛn.",
  "Club/player reviews and audit": "Luk klob/pleya ɛn audit",
  "Review club profile changes, player registrations and transfer requests in their respective queues.": "Luk chenj fɔ klob prɔfayl, rijistreshɔn fɔ pleya ɛn rikwest fɔ transfer na di list dɛn we fɔlɔ dɛn.",
  "Approve only complete, verified information. Use the audit log to review recorded changes.": "Apruv infomeshɔn we don fɛnish ɛn dɛn don chɛk nɔmɔ. Yuz audit log fɔ luk chenj dɛn we dɛn don rikɔd.",
  "Review fan reports according to SLFA policy.": "Luk ripɔt fɔ fan dɛn fɔlɔ SLFA polisi.",
  "Downloads and backups": "Dɔnlod ɛn backup dɛn",
  "Download match/results, standings or suspension CSV files for authorized reporting.": "Dɔnlod CSV fayl fɔ mach/rizɔlt, tebul ɔ suspenzɔn fɔ ripɔt we dɛn apruv.",
  "Use Full backup (JSON) only when a complete data export is required and store it securely.": "Yuz Full backup (JSON) nɔmɔ wen yu nid fɔ export ɔl data, ɛn kip am na sef ples.",
  "Exports are recorded. Never share exported personal or operational data without authorization.": "Dɛn de rikɔd export dɛn. Neba share pɔsin infomeshɔn ɔ data fɔ wok we dɛn export nɔto wit pɔmit.",
  "Referee User Manual": "Manyual fɔ Refri",
  "This portal is for officials assigned to matches. Only work on a fixture assigned to your signed-in account.": "Dis portal na fɔ ɔfishal dɛn we dɛn gi mach. Wok na mach we dɛn assign gi akawnt we yu de yuz nɔmɔ.",
  "Choose your match": "Pik yu mach",
  "Open My matches and select the assigned fixture from the list.": "Opɛn Mi mach dɛn ɛn pik mach we dɛn gi yu na list.",
  "If no fixture appears, confirm you are signed in with the correct account and ask the Super Admin to verify the assignment.": "Sɛ mach nɔ sho, kɔnfɔm se yu sayn in wit di rait akawnt ɛn aks Big Admin fɔ chɛk di jɔb we dɛn gi yu.",
  "Start and manage match time": "Bigin ɛn manij tɛm fɔ mach",
  "Select the correct match before using any match controls.": "Pik di rait mach bifo yu yuz eni kɔntrol fɔ mach.",
  "Use Start match when play begins. Use the half-time and second-half controls at the appropriate points.": "Yuz Bigin mach wen ple de bigin. Yuz kɔntrol fɔ mid-tɛm ɛn di sekɔn haf na di rait tɛm.",
  "Update the current minute when required and verify the displayed match clock/status.": "Apdet minit we mach don ple wen e nid, ɛn chɛk klok/stetis we de sho.",
  "Record match events": "Rikɔd wetin apin na mach",
  "Choose the team, enter the player name and match minute, then select Goal, Yellow card, Red card or Substitution.": "Pik tim, put nem fɔ pleya ɛn minit fɔ mach, den pik Gɔl, Yɛlo kad, Rɛd kad ɔ chenj pleya.",
  "For a goal, enter the assist player only when applicable.": "Fɔ gɔl, put nem fɔ pleya we gi asist nɔmɔ sɛ e de ɛn nid.",
  "For a substitution, enter the player coming off as well as the player coming on.": "Fɔ chenj pleya, put pleya we de kɔmɔt ɛn pleya we de kam insay.",
  "Review the event list and score after recording. Correct errors promptly using the approved process.": "Luk list fɔ wetin apin ɛn skɔ afta yu rikɔd am. Fiks ɛrɔ kwik wit di process we dɛn apruv.",
  "Submit the final score": "Sɛnd final skɔ",
  "At full time, verify the goals recorded for both teams against the official match record.": "Wen mach don ɛnd, chɛk gɔl we dɛn rikɔd fɔ tu tim ɛn kɔmpɛa am wit ɔfishal mach rikɔd.",
  "Select End and save final score and confirm the displayed score for approval.": "Pik End ɛn sev final skɔ, den kɔnfɔm skɔ we de sho fɔ apruv.",
  "A submitted score may be awaiting Super Admin approval before it is treated as confirmed. Do not submit until checked.": "Skɔ we yu sɛnd fit de wet fɔ Big Admin apruv bifo dɛn go kɔnsidɛ am se dɛn don kɔnfɔm. Nɔ sɛnd am bifo yu chɛk am.",
  "Change or reverse a result": "Chenj ɔ kansul wan rizɔlt",
  "These actions affect an already submitted final score. Use them only when an authorized correction is required.": "Dis wok dɛn de chenj final skɔ we dɛn don sɛnd. Yuz dɛn nɔmɔ wen pɔsin we gɛt pɔmit nid fɔ korekt am.",
  "Provide a clear reason when prompted. Changes and reversals are logged.": "Gi klia rizɔn wen dɛn aks yu. Dɛn de rikɔd chenj ɛn kansul.",
  "If unsure, contact the Super Admin before proceeding.": "Sɛ yu nɔ shɔ, kɔntakt Big Admin bifo yu go fɔwod.",
  "Choose the match and select the eligible player from the Man of the Match list.": "Pik mach ɛn pik pleya we fit fɔ win frɔm list fɔ Man fɔ di Mach.",
  "Check the player and fixture carefully before saving the award.": "Chɛk pleya ɛn mach gud bifo yu sev di award.",
  "Offline use and synchronization": "Yuz wen intanɛt nɔ de ɛn sink",
  "Match events and final scores may be queued on this device when the internet is unavailable.": "Wetin apin na mach ɛn final skɔ fit de na queue na dis divays wen intanɛt nɔ de.",
  "Keep the portal open and return to a reliable connection. The app attempts to sync queued items automatically.": "Kip portal opɛn ɛn go na intanɛt we gud. Di app go tray fɔ sink item dɛn we de na queue ɔtomatik.",
  "Wait for a successful sync message before assuming the server has received the report. Avoid repeated submissions.": "Luk message we tɔk se sink don wok bifo yu biliv se server don gɛt ripɔt. Nɔ sɛnd sem tin plenti tɛm.",
  "Create a news post": "Mek nyuz post",
  "Choose a category: News, Press release, Match report or Announcement.": "Pik kayɛgori: Nyuz, Press release, Ripɔt fɔ mach ɔ Anawsmɛnt.",
  "For a match report, optionally link the completed match. Select the relevant competition, or leave All leagues for general news.": "Fɔ ripɔt fɔ mach, yu fit link mach we don ɛnd. Pik kɔmpitishɔn we e fɔ, ɔ lef Ɔl lig dɛn fɔ nyuz fɔ ɔlman.",
  "Enter a clear headline and write the story. Add a photo or video URL only if it is valid and approved for publication.": "Put klia taitul ɛn rait stori. Ad foto ɔ vidio URL nɔmɔ sɛ e valid ɛn dɛn apruv am fɔ publish.",
  "Review spelling, names, dates and links before saving.": "Luk spel, nem, dɛt ɛn link dɛn bifo yu sev.",
  "Save a draft or submit": "Sev draf ɔ sɛnd am",
  "Choose Save draft to keep work in progress. Drafts are not public.": "Pik Sev draf fɔ kip wok we nɔ don fɛnish. Pɔblik nɔ go si draf.",
  "Choose Submit for approval when the post is ready. A Super Admin reviews it before it appears in the public News Centre.": "Pik Sɛnd fɔ apruv wen post don redi. Big Admin go luk am bifo e go apia na pɔblik News Centre.",
  "Check My posts to see each item and its status. If a draft needs approval, use Submit for approval there.": "Chɛk Mi post dɛn fɔ si ɛni item ɛn im stetis. Sɛ draf nid apruv, yuz Sɛnd fɔ apruv na de.",
  "Create a fan poll": "Mek poll fɔ fan dɛn",
  "Enter a neutral, clear question and at least two answer options. A third and fourth option are optional.": "Put kwɛshɔn we nɔ de pik wan sid ɛn we klia. Put lɛst tu ansa. Yu fit ad di tɔd ɛn fɔt ansa sɛ yu want.",
  "Select Publish poll and confirm that the question and options appear in the poll list.": "Pik Publish poll ɛn kɔnfɔm se kwɛshɔn ɛn ansa dɛn de na list fɔ poll.",
  "Use Close poll when voting should stop. Reopen poll only when authorized and appropriate.": "Yuz Klos poll wen votin fɔ stop. Opɛn poll bak nɔmɔ wen yu gɛt pɔmit ɛn e fɔ.",
  "Editorial standards": "Standad fɔ rait nyuz",
  "Use verified information and accurate competition, club, player and match names.": "Yuz infomeshɔn we dɛn don chɛk ɛn rait nem fɔ kɔmpitishɔn, klob, pleya ɛn mach.",
  "Obtain permission for photographs, video and personal information before submission.": "Gɛt pɔmit fɔ foto, vidio ɛn infomeshɔn fɔ pɔsin bifo yu sɛnd am.",
  "Do not present an unapproved draft as an official SLFA announcement.": "Nɔ sho draf we dɛn nɔ apruv se na ɔfishal SLFA anawsmɛnt.",
  "Correct errors through the appropriate review process and follow SLFA media policy.": "Korekt ɛrɔ tru di rait review process ɛn fɔlɔ SLFA media polisi.",
  "Disciplinary Officer User Manual": "Manyual fɔ Disiplin Ɔfisɛ",
  "Use this portal to record disciplinary decisions and manage suspension rules. Enter only verified decisions made through the authorized process.": "Yuz dis portal fɔ rikɔd disizɔn fɔ disiplin ɛn manij rul fɔ suspenzɔn. Put disizɔn we dɛn don chɛk ɛn mek tru process we dɛn apruv nɔmɔ.",
  "Review suspensions": "Luk suspenzɔn dɛn",
  "Open the Suspensions list to review current disciplinary records.": "Opɛn list fɔ Suspenzɔn fɔ luk rikɔd fɔ disiplin nɔw.",
  "Check the player, competition and remaining suspension details before taking further action.": "Chɛk pleya, kɔmpitishɔn ɛn tɛm we lef fɔ suspenzɔn bifo yu du ɔda wok.",
  "Record a decision": "Rikɔd disizɔn",
  "Choose the correct player and decision type: Note, Protest, Official ruling, Fine or Match ban.": "Pik di rait pleya ɛn kain fɔ disizɔn: Not, Protest, Ɔfishal rul, Fine ɔ Ban fɔ mach.",
  "For a fine, enter the fine amount. For a match ban, enter the number of matches.": "Fɔ fine, put di amɔnt. Fɔ ban fɔ mach, put nɔmba fɔ mach dɛn.",
  "Link a related match when relevant and enter a clear reason or ruling.": "Link mach we konek wit dis mata sɛ e fɔ, ɛn put klia rizɔn ɔ rul.",
  "Choose whether the decision should appear on the public player profile in accordance with SLFA policy.": "Pik sɛ dis disizɔn fɔ sho na pɔblik prɔfayl fɔ pleya fɔlɔ SLFA polisi.",
  "Select Record decision and verify that the new record appears in the list.": "Pik Rikɔd disizɔn ɛn chɛk se nyu rikɔd don apia na list.",
  "Configure disciplinary rules": "Set rul fɔ disiplin",
  "Set the yellow-card accumulation threshold and the number of matches for the resulting ban.": "Set nɔmba fɔ yɛlo kad we go mek ban, ɛn nɔmba fɔ mach we ban go las.",
  "Set the suspension length for a straight red card.": "Set tɛm we ban fɔ rɛd kad we dɛn gi strɛt go las.",
  "Check every value against the current competition regulations before saving rules.": "Chɛk ɛni nɔmba ɛn infomeshɔn wit rul fɔ kɔmpitishɔn we de nɔw bifo yu sev rul dɛn.",
  "Do not change rules during a competition without the appropriate authorization.": "Nɔ chenj rul dɛn we kɔmpitishɔn de go nɔto sɛ yu gɛt di rait pɔmit.",
  "Accuracy, privacy and corrections": "Raitnɛs, privasi ɛn korekshɔn",
  "Confirm the player identity and supporting match record before saving.": "Kɔnfɔm pɔsin we pleya na im tru ɛn rikɔd fɔ mach bifo yu sev.",
  "Use clear, factual language. Avoid publishing confidential case details.": "Yuz klia toktok we tru. Nɔ publish infomeshɔn fɔ kes we fɔ kip sikrit.",
  "If a decision is incorrect, follow the official correction or appeal process and retain the proper record.": "Sɛ disizɔn nɔ rait, fɔlɔ ɔfishal process fɔ korekt am ɔ appeal, ɛn kip di rait rikɔd."
});

  
  // Krio translations for public forms, guidance, privacy and account pages.
