  "Private SLFA operations portal. Access is limited to active Club Representatives assigned by the Technical Director.": "Dis na privet portal fɔ SLFA wok. Na klob riprɛsɛntativ we de wok ɛn we Teknikal Direktɔ gi jɔb nɔmɔ fit ɛntə.",
  "Authorised match data operator sign in": "Sayn in fɔ mach data woka we dɛn apruv",
  "Private SLFA match operations portal. Access is limited to active Match Data Operators appointed to fixtures by the Super Admin.": "Dis na privet portal fɔ SLFA mach wok. Na Match Data Operator we de wok ɛn we Big Admin gi mach nɔmɔ fit ɛntə.",
  "Team Official": "Tim Ɔfishal",
  "Referee": "Refri",
