  "Super Admin only. Maintain official competition profiles, season dates, venues, format details and publication status. Published information appears in the public League Pages without changing application code.": "Na Big Admin nɔmɔ fɔ manij ɔfishal prɔfayl fɔ kɔmpitishɔn, dɛt fɔ sezon, ples fɔ mach, fɔmat ɛn status fɔ publish. Infomeshɔn we dɛn publish go sho na pɔblik League Pages witawt fɔ chenj app code.",
  "Existing competition": "Kɔmpitishɔn we de finis",
