  "Display order": "Ɔda fɔ sho",
  "Publish this competition in the public app": "Publish dis kɔmpitishɔn na pɔblik app",
  "Save competition": "Sev kɔmpitishɔn",
  "New competition": "Nyu kɔmpitishɔn",
  "Loading competitions…": "Di kɔmpitishɔn dɛn de lod…",
  "Records and Rules · Official content editor": "Rikɔd ɛn Rul · ɔfishal ples fɔ edit kontɛnt",
  "Super Admin only. Maintain published competition points and tie-break settings. Enter only rules confirmed by the Association.": "Na Big Admin nɔmɔ fɔ manij pɔynt fɔ kɔmpitishɔn we dɛn publish ɛn rul fɔ break tie. Put rul we Association don kɔnfɔm nɔmɔ.",
  "Existing rule profile": "Rul prɔfayl we de finis",
